<title>Qahwa Lab - Ramadan Campaign / مختبر القهوة - حملة رمضان</title>
<style>
  :root {
    --primary-color: #2C1810;
    --accent-color: #D4AF37;
    --bg-color: #FDFBF7;
    --text-color: #333333;
    --card-bg: #FFFFFF;
  }
  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }
  body {
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    background-color: var(--bg-color);
    color: var(--text-color);
    line-height: 1.6;
  }
  header {
    background-color: var(--primary-color);
    color: var(--accent-color);
    padding: 2rem 1rem;
    text-align: center;
  }
  header h1 {
    font-size: 2rem;
    margin-bottom: 0.5rem;
  }
  header p {
    color: #FFFFFF;
    font-size: 1rem;
  }
  .container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem 1rem;
  }
  .grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  @media (min-width: 768px) {
    .grid {
      grid-template-columns: 1fr 1fr;
    }
  }
  .card {
    background-color: var(--card-bg);
    border: 1px solid #E5DCC3;
    border-radius: 8px;
    padding: 2rem;
    box-shadow: 0 4px 6px rgba(0,0,0,0.02);
  }
  .card h2 {
    color: var(--primary-color);
    margin-bottom: 1rem;
    font-size: 1.5rem;
    border-bottom: 2px solid var(--accent-color);
    padding-bottom: 0.5rem;
    display: inline-block;
  }
  .card p {
    margin-bottom: 1.5rem;
  }
  .highlight-box {
    background-color: #F4EEDC;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1.5rem;
  }
  .highlight-box h3 {
    color: var(--primary-color);
    margin-bottom: 0.5rem;
  }
  .highlight-box ul {
    list-style-type: disc;
    margin-right: 1.5rem;
    margin-left: 1.5rem;
  }
  .highlight-box li {
    margin-bottom: 0.5rem;
  }
  .code {
    font-weight: bold;
    color: var(--primary-color);
    background: var(--accent-color);
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    display: inline-block;
  }
  .btn {
    display: inline-block;
    background-color: var(--primary-color);
    color: var(--accent-color);
    padding: 0.75rem 1.5rem;
    border-radius: 4px;
    text-decoration: none;
    font-weight: bold;
    text-align: center;
    transition: opacity 0.2s;
  }
  .btn:hover {
    opacity: 0.9;
  }
  footer {
    background-color: var(--primary-color);
    color: #FFFFFF;
    text-align: center;
    padding: 2rem 1rem;
    margin-top: 3rem;
  }
  footer p {
    margin-bottom: 0.25rem;
  }
  .meta {
    font-size: 0.9rem;
    color: var(--accent-color);
  }
</style>
</head>
